<script setup lang="ts">
import {reusableTransitionInputs,reuseTransitionInputs} from '../shared/transition-inputs';
import BulkRecordEditor from './BulkRecordEditor.vue';
import type {BulkRequest} from '../shared/bulk-records';
import {useTransitionPlans} from './use-transition-plans';
import type {RelatedRecord} from '../shared/record-navigation';
import {computed,ref,watch,onMounted,onUpdated} from 'vue';
import type {Component,Database,InventoryPC} from '../shared/types';
import {locationPath} from '../shared/installations';
import {newTransitionScenario,transitionScenarioSchema,transitionMatches,transitionCohorts,transitionOptions,requiredSegmentGb,planTransition,ssdCandidates,transitionBaseline,segmentsFor} from '../shared/transitions';
import type {ReusableTransitionInputs} from '../shared/transition-inputs';
import type {TransitionCohort,Segment} from '../shared/transitions';
import RecordTable from './RecordTable.vue';
const props=defineProps<{db:Database;revision:string}>();
const emit=defineEmits<{reload:[];editPc:[pc:InventoryPC];openInstallations:[];editComponent:[component:Component];notify:[message:string];openRelated:[record:RelatedRecord]}>();
const scenario=ref(newTransitionScenario()),reviewed=ref(''),fileRevision=ref(props.revision),error=ref('');
watch(()=>scenario.value.pcIds,ids=>{const pilots=scenario.value.rollout.pilotPCIds.filter(id=>ids.includes(id));if(pilots.length!==scenario.value.rollout.pilotPCIds.length)scenario.value.rollout.pilotPCIds=pilots;},{deep:true});
function labelTables(){for(const wrapper of document.querySelectorAll<HTMLElement>('.transitions-workspace .v-table__wrapper')){wrapper.tabIndex=0;wrapper.setAttribute('role','region');wrapper.setAttribute('aria-label',`${wrapper.querySelector('caption')?.textContent||'Transition planning table'}; scroll to view all columns`);}}
onMounted(labelTables);onUpdated(labelTables);
const {awaitReady,plans,activeId,selectedPlan,planBusy,planLoading,plansError,autosaveState,hasUnsavedChanges,confirmDiscard,newPlan,openWorkspacePlan,importedPlan,deletePlan,saveWorkspacePlan,retryDraft}=useTransitionPlans(scenario,fileRevision,reviewed,()=>props.revision);
const planChoices=computed(()=>plans.value.map(p=>({title:`${(p.draft??p.scenario)!.name||'Untitled plan'}${p.draft?' · draft available':''}`,value:p.id})));
const recoverable=computed(()=>plans.value.filter(p=>p.draft).sort((a,b)=>b.updatedAt.localeCompare(a.updatedAt)));
const bulkRequest=ref<BulkRequest|null>(null),bulkEditor=ref<InstanceType<typeof BulkRecordEditor>|null>(null);
function confirmAllDiscard(){return (bulkEditor.value?.confirmDiscard()??true)&&confirmDiscard();}
function getContext(){return {planId:plans.value.some(p=>p.id===activeId.value)?activeId.value:'',reviewed:reviewed.value,scopeSearch:scopeSearch.value,selectedOnly:selectedOnly.value,blockersOnly:blockersOnly.value,orderOnly:orderOnly.value,estimateBasis:estimateBasis.value};}
async function restoreContext(context:ReturnType<typeof getContext>){await openWorkspacePlan(context.planId);reviewed.value=context.reviewed;scopeSearch.value=context.scopeSearch;selectedOnly.value=context.selectedOnly;blockersOnly.value=context.blockersOnly;orderOnly.value=context.orderOnly;estimateBasis.value=context.estimateBasis||'confirmed';}
async function openRoute(id:string,context?:ReturnType<typeof getContext>){await awaitReady();if(id)await openWorkspacePlan(id,false,true);else newPlan(true);scopeSearch.value=context?.scopeSearch||'';selectedOnly.value=context?.selectedOnly||false;blockersOnly.value=context?.blockersOnly??true;orderOnly.value=context?.orderOnly??true;estimateBasis.value=context?.estimateBasis||'confirmed';reviewed.value=context?.reviewed||'';}
defineExpose({hasUnsavedChanges:()=>hasUnsavedChanges()||!!bulkEditor.value?.hasUnsavedChanges(),confirmDiscard:confirmAllDiscard,getContext,restoreContext,openRoute});
const parsed=computed(()=>transitionScenarioSchema.safeParse(scenario.value));
const validationError=computed(()=>parsed.value.success?'':parsed.value.error.issues[0]?.message||'Check plan inputs.');
const scopeSearch=ref(''),scopePage=ref(1),selectedOnly=ref(false),sharedDestination=ref(''),blockersOnly=ref(true),orderOnly=ref(true),estimateBasis=ref<'confirmed'|'conditional'>('confirmed');
const reuseSource=ref<Record<string,string>>({});
const matches=computed(()=>transitionMatches(props.db,scenario.value).filter(pc=>`${pc.name} ${pc.serial} ${pc.location} ${locationPath(pc.installationLocationId||'',props.db)}`.toLowerCase().includes(scopeSearch.value.toLowerCase())));
watch(()=>matches.value.map(pc=>pc.id).join('\0'),()=>scopePage.value=1);
const cohorts=computed(()=>transitionCohorts(props.db,scenario.value));
const fingerprint=computed(()=>JSON.stringify(scenario.value)+props.revision);
const currentReview=computed(()=>reviewed.value===fingerprint.value);
const stale=computed(()=>fileRevision.value!==props.revision);
const report=computed(()=>parsed.value.success?planTransition(props.db,parsed.value.data):null);
const sourceChoices=computed(()=>props.db.configurations.map(c=>({title:`${c.name} · ${props.db.pcs.filter(p=>(p.hardwareSurvey&&p.hardwareSurvey.status!=='complete'?p.hardwareSurvey.configurationId:p.configurationId)===c.id&&!['Retired','Parts only'].includes(p.lifecycle||'')).length} active PCs`,value:c.id})));
const locationChoices=computed(()=>[{title:'All installations',value:''},...props.db.installationLocations.map(l=>({title:locationPath(l.id,props.db),value:l.id}))]);
const unknownDrives=computed(()=>props.db.components.filter(c=>c.category==='Drive'&&c.specs.driveKind!=='optical'&&c.specs.driveSize!=='5.25'&&!c.specs.storageMedium));
const scopeRows=computed(()=>(selectedOnly.value?props.db.pcs.filter(pc=>scenario.value.pcIds.includes(pc.id)):matches.value).map(pc=>{const baseline=transitionBaseline(pc,props.db);return {...pc,configuration:props.db.configurations.find(c=>c.id===(pc.hardwareSurvey&&pc.hardwareSurvey.status!=='complete'?pc.hardwareSurvey.configurationId:pc.configurationId))?.name||'Unlinked',physicalLocation:locationPath(pc.installationLocationId||'',props.db)||pc.location||'Unassigned',baseline:baseline.provisional?'Hardware assumption':'Recorded hardware',baselineIssue:baseline.issues[0]||'',media:[...new Set(baseline.configuration?.placements.map(p=>props.db.components.find(c=>c.id===p.componentId)).filter(c=>c?.category==='Drive').map(c=>c!.specs.storageMedium||'Unknown')||[])].join(' / ')};}));
const scopeHeaders=[{title:'PC',key:'name'},{title:'Source configuration',key:'configuration'},{title:'Location',key:'physicalLocation'},{title:'Baseline',key:'baseline'},{title:'Storage media',key:'media'},{title:'Survey / action',key:'surveyAction',sortable:false}];
const selectedHidden=computed(()=>scenario.value.pcIds.filter(id=>!matches.value.some(pc=>pc.id===id)).length);
const unavailableIds=computed(()=>scenario.value.pcIds.filter(id=>{const pc=props.db.pcs.find(p=>p.id===id);return !pc||['Retired','Parts only'].includes(pc.lifecycle||'');}));
function removePCs(ids:string[]){const remove=new Set(ids);scenario.value.pcIds=scenario.value.pcIds.filter(id=>!remove.has(id));}
function editSelected(){bulkRequest.value={collection:'pcs',action:'edit',ids:scenario.value.pcIds.filter(id=>props.db.pcs.some(pc=>pc.id===id)),patch:{}};}
function clearSelection(){selectedOnly.value=false;scenario.value.pcIds=[];scenario.value.rollout.pilotPCIds=[];}
function addMatches(){scenario.value.pcIds=[...new Set([...scenario.value.pcIds,...matches.value.map(pc=>pc.id)])];}
function policy(cohort:TransitionCohort,segment:Segment){return scenario.value.policies[cohort.id]?.[segment.id];}
function updatePolicy(cohort:TransitionCohort,segment:Segment,key:'replacementId'|'targetSegmentId'|'usedGb'|'evidence',value:unknown){
 const policies=scenario.value.policies[cohort.id]??={};const entry=policies[segment.id]??={evidence:''};
 if(key==='usedGb'){if(value===''||value===null||value===undefined)delete entry.usedGb;else entry.usedGb=Number(value);}
 else if(key==='replacementId'||key==='targetSegmentId'){if(value)entry[key]=String(value);else delete entry[key];}
 else entry.evidence=String(value||'');
}
function destinationSegments(cohort:TransitionCohort){const configuration=props.db.configurations.find(c=>c.id===scenario.value.destinationIds[cohort.id]);return configuration?segmentsFor({...cohort.members[0],configuration},props.db):[];}
const destinationChoices=computed(()=>props.db.configurations.map(c=>({title:`${c.name} · ${c.status}`,value:c.id})));
const options=computed(()=>new Map((scenario.value.mode==='ssd'?cohorts.value:[]).flatMap(cohort=>cohort.segments.map(segment=>[`${cohort.id}\0${segment.id}`,transitionOptions(cohort,segment,scenario.value,props.db)] as const))));
function choices(cohort:TransitionCohort,segment:Segment){return options.value.get(`${cohort.id}\0${segment.id}`)||[];}
function applySharedDestination(){if(sharedDestination.value)for(const cohort of cohorts.value)scenario.value.destinationIds[cohort.id]=sharedDestination.value;}
const resultRows=computed(()=>report.value?.pcs.filter(pc=>!blockersOnly.value||!report.value?.blocked||pc.status==='Blocked').map(pc=>({...pc,reviewText:[pc.status,...pc.issues,...pc.warnings].join(' ')}))||[]);
const orderRows=computed(()=>report.value?.procurement.filter(row=>!orderOnly.value||(estimateBasis.value==='conditional'?row.orderIfConfirmed:row.order)>0).map(row=>({...row,componentSummary:`${row.name} ${row.category} ${row.interface} ${row.size} ${row.capacityGb??''}`}))||[]);
const orderCount=computed(()=>report.value?.procurement.reduce((total,row)=>total+row.order,0)||0);
const conditionalOrderCount=computed(()=>report.value?.procurement.reduce((total,row)=>total+row.orderIfConfirmed,0)||0);
const hasAssumedReuse=computed(()=>report.value?.procurement.some(row=>row.assumedRetained>0));
const exportReason=computed(()=>!scenario.value.pcIds.length?'Select PCs to prepare an order estimate.':report.value?.blocked?'Resolve blocked PCs before exporting an order.':!currentReview.value||stale.value?'Review the current plan to enable order export.':!report.value?.procurement.length?'No resolved parts demand to export.':'The CSV includes both estimates and the full stock calculation, regardless of the table filters.');
const reusableGroups=computed(()=>new Map(cohorts.value.map(cohort=>[cohort.id,reusableTransitionInputs(cohort,scenario.value,props.db)])));
function reuseChoices(cohort:TransitionCohort){return reusableGroups.value.get(cohort.id)||[];}
function reusePreview(cohort:TransitionCohort){const choices=reuseChoices(cohort);return choices.length===1?choices[0]:choices.find(choice=>choice.key===reuseSource.value[cohort.id]);}
function reuseSummary(choice:ReusableTransitionInputs){const destination=props.db.configurations.find(c=>c.id===choice.destinationId)?.name||'Current destination kept';const used=Object.entries(choice.policies).filter(([,p])=>p.usedGb!==undefined).map(([id,p])=>`${id}: ${gb(p.usedGb)} used`).join('; ');return `${destination} · ${used||'No measured usage to copy'}`;}
function copyInputs(cohort:TransitionCohort){const key=reusePreview(cohort)?.key;if(!key)return;const result=reuseTransitionInputs(cohort,key,scenario.value,props.db);if(result)emit('notify',`Reused available inputs from ${result.name}.${result.skipped?` ${result.skipped} changed array inputs were left blank.`:''} Review capacity evidence for this group before exporting.`);}
function suggest(cohort:TransitionCohort){for(const segment of cohort.segments){const option=choices(cohort,segment).find(c=>c.eligible);if(option)updatePolicy(cohort,segment,'replacementId',option.id);}}
function review(){if(!parsed.value.success)return;reviewed.value=fingerprint.value;fileRevision.value=props.revision;}
function download(name:string,content:string,type:string){const url=URL.createObjectURL(new Blob([content],{type}));const link=document.createElement('a');link.href=url;link.download=name;link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function savePlan(){if(!parsed.value.success)return;download('configuration-transition-plan.json',JSON.stringify({version:1,scenario:scenario.value,workspaceRevision:props.revision,generatedAt:new Date().toISOString(),reviewed:currentReview.value,report:report.value},null,2),'application/json');emit('notify','Transition plan file exported. Workspace drafts are stored separately from this export.');}
async function openPlan(event:Event){const input=event.target as HTMLInputElement,file=input.files?.[0];input.value='';if(!file)return;error.value='';try{
 if(file.size>20*1024*1024)throw Error('Plan files must be under 20 MiB.');
 const body=JSON.parse(await file.text());if(body.version!==1||typeof body.workspaceRevision!=='string')throw Error('Unsupported transition plan file.');
 const parsedDraft=transitionScenarioSchema.safeParse(body.scenario);if(!parsedDraft.success)throw Error(`Invalid plan inputs: ${parsedDraft.error.issues[0]?.message||'Check the file format.'}`);const draft=parsedDraft.data;if(!confirmAllDiscard())return;
 importedPlan(draft,body.workspaceRevision);
 }catch(e){error.value=e instanceof Error?e.message:String(e);}}
function exportOrder(){if(!report.value||!currentReview.value||report.value.blocked||stale.value)return;
 const rows=[['Component','Category','Interface','Form factor','Capacity GB per unit','Target units','Retain installed','Possible assumed reuse','Held reservations','Spare units','Free serviceable stock','Order units (confirmed stock only)','Order units if assumptions confirmed'],...report.value.procurement.map(r=>[r.name,r.category,r.interface,r.size,r.capacityGb??'',r.target,r.retained,r.assumedRetained,r.reserved,r.spares,r.free,r.order,r.orderIfConfirmed])];
 const escape=(value:unknown)=>{let text=String(value);if(/^[=+\-@\t\r]/.test(text))text="'"+text;return '"'+text.replaceAll('"','""')+'"';};
 download('configuration-transition-order.csv',rows.map(row=>row.map(escape).join(',')).join('\r\n'),'text/csv;charset=utf-8');
}
const gb=(n:number|null|undefined)=>n==null||!Number.isFinite(n)?'Unknown':`${Math.ceil(n).toLocaleString()} GB`;
const resultHeaders=[{title:'PC',key:'name'},{title:'Source',key:'source'},{title:'Destination',key:'destination'},{title:'Baseline',key:'provisional'},{title:'Boot before → after',key:'afterBoot'},{title:'Data before → after',key:'afterData'},{title:'Review',key:'reviewText'}];
const waveHeaders=[{title:'Phase',key:'phase'},{title:'PCs',key:'count'},{title:'Machines',key:'pcs'},{title:'Hardware assumptions',key:'provisional'}];
const pilotChoices=computed(()=>scenario.value.pcIds.map(id=>({title:props.db.pcs.find(p=>p.id===id)?.name||id,value:id})));
const orderHeaders=[{title:'Component',key:'componentSummary'},{title:'Target units',key:'target'},{title:'Order (confirmed stock)',key:'order'},{title:'Order if assumptions confirmed',key:'orderIfConfirmed'},{title:'Stock calculation',key:'breakdown',sortable:false}];
</script>
<template>
<div class="transitions-workspace">
<div class="page-heading"><div><h1>Configuration transitions</h1><p>Plan hardware changes across a fleet, compare capacities, and estimate the complete parts order.</p></div><div class="heading-actions"><label class="plan-file-button">Open plan file<input type="file" accept=".json,application/json" :disabled="planBusy||planLoading" @change="openPlan" /></label><v-btn variant="outlined" :disabled="!!validationError||planLoading" @click="savePlan">Export plan file</v-btn></div></div>
<section class="panel build-notes control-stack"><h2>Workspace plans</h2><p>Saved plans and autosaved drafts travel with the workspace and its JSON backups.</p><v-select v-model="selectedPlan" :items="planChoices" label="Saved workspace plans" :disabled="planBusy||planLoading" /><div class="heading-actions"><v-btn variant="outlined" :disabled="!selectedPlan||planBusy||planLoading" @click="openWorkspacePlan(selectedPlan)">Open plan / resume draft</v-btn><v-btn v-if="plans.find(p=>p.id===selectedPlan)?.scenario&&plans.find(p=>p.id===selectedPlan)?.draft" variant="text" :disabled="planBusy||planLoading" @click="openWorkspacePlan(selectedPlan,true)">Open saved inputs</v-btn><v-btn color="primary" :disabled="!!validationError||planBusy||planLoading" :loading="planBusy" @click="saveWorkspacePlan">Save plan in workspace</v-btn><v-btn variant="outlined" :disabled="planBusy||planLoading" @click="newPlan">New plan</v-btn><v-btn v-if="plans.some(p=>p.id===activeId)" color="error" variant="text" :disabled="planBusy||planLoading" @click="deletePlan">Delete workspace plan</v-btn></div><p role="status">{{autosaveState}}</p><v-alert v-if="recoverable.length&&!plans.some(p=>p.id===activeId)" type="info">{{recoverable.length}} workspace drafts available.<v-btn variant="text" :disabled="planBusy||planLoading" @click="openWorkspacePlan(recoverable[0].id)">Resume latest draft</v-btn></v-alert><v-alert v-if="plansError" type="error" role="alert">{{plansError}}<v-btn variant="text" :disabled="planBusy" @click="retryDraft">Retry saving draft</v-btn></v-alert></section>
<v-alert v-if="error||validationError" type="error" role="alert" class="mb-5">{{error||validationError}}</v-alert>
<v-alert v-if="stale" type="warning" class="mb-5">The workspace changed since this plan was opened or reviewed. Results use current records and stock; review again before exporting an order.</v-alert>
<div :inert="planLoading"><section class="panel build-notes control-stack"><h2>1. Select the fleet</h2><p>Choose one or several older configurations, an installation scope, or individual PCs. Retired and parts-only PCs are excluded from matching results.</p><div class="form-grid"><v-text-field v-model="scenario.name" label="Plan name" /><v-select v-model="scenario.sourceIds" :items="sourceChoices" label="Source configurations (empty means all)" multiple chips closable-chips clearable /><v-select v-model="scenario.locationId" :items="locationChoices" label="Installation scope (includes descendants)" /><v-checkbox v-model="scenario.onlyHDD" label="Only PCs whose baseline includes an HDD" hide-details /></div>
<div class="bulk-toolbar"><v-btn variant="outlined" :disabled="!matches.length||new Set([...scenario.pcIds,...matches.map(pc=>pc.id)]).size>500" @click="addMatches">Add all {{matches.length}} matching PCs</v-btn><v-btn variant="text" :disabled="!scenario.pcIds.length" @click="clearSelection">Clear selection</v-btn><v-btn variant="outlined" :disabled="!scenario.pcIds.some(id=>db.pcs.some(pc=>pc.id===id))||scenario.pcIds.length>500" @click="editSelected">Edit selected PCs</v-btn><v-btn v-if="unavailableIds.length" variant="text" @click="removePCs(unavailableIds)">Remove {{unavailableIds.length}} unavailable PCs</v-btn><v-btn v-if="selectedHidden" variant="text" @click="selectedOnly=true">Show {{selectedHidden}} selected PCs hidden by filters</v-btn><p role="status">{{scenario.pcIds.length}} selected · {{selectedHidden}} hidden by scope filters. Up to 500 PCs; selection stays explicit when filters change.</p></div>
<v-alert v-if="!db.pcs.length" type="info">Register known devices before selecting a fleet.<v-btn variant="text" @click="emit('openInstallations')">Open installation locations</v-btn></v-alert><v-checkbox v-model="selectedOnly" label="Review selected PCs (including those hidden by scope)" hide-details class="mb-4" /><v-text-field v-if="!selectedOnly" :model-value="scopeSearch" @update:model-value="v=>scopeSearch=String(v??'')" clearable label="Search PCs in scope" hide-details class="mb-4" />
<v-data-table v-model="scenario.pcIds" v-model:page="scopePage" :headers="scopeHeaders" :items="scopeRows" item-value="id" show-select select-strategy="page" :items-per-page="25" :items-per-page-options="[10,25,50,100]" :mobile="false"><template #item.surveyAction="{item}"><small v-if="item.baselineIssue">{{item.baselineIssue}}</small><v-btn variant="text" size="small" @click="emit('editPc',db.pcs.find(pc=>pc.id===item.id)!)">Edit survey<span class="sr-only"> for {{item.name}}</span></v-btn></template><template #item.name="{item}"><button type="button" class="table-name" @click="emit('openRelated',{kind:'pc',id:item.id})">{{item.name}}</button></template><template #caption><caption class="sr-only">PCs available for the transition plan</caption></template><template #item.data-table-select="{item,internalItem,index,props:checkbox,toggleSelect}"><v-checkbox-btn v-bind="{...checkbox,onClick:undefined}" @click.stop="(event:MouseEvent)=>toggleSelect(internalItem,index,event)" :aria-label="`Include PC ${item.name}`" /></template></v-data-table>
<p>PCs with incomplete surveys use their documented current configuration assumption, even when some parts have been recorded. Conflicting recorded parts block planning. PCs without a survey status keep the existing installed-hardware / linked-configuration fallback. Register known devices from Installations, then use the PC editor to update their survey status. Hardware variations and pinned capacity requirements form separate planning groups.</p>
<details v-if="unknownDrives.length"><summary>{{unknownDrives.length}} catalog drives have an unknown storage medium</summary><p>Record HDD or SSD in the component catalog. The planner does not infer the medium from a name or from SATA/NVMe. Unknown drives are excluded from the HDD filter and SSD choices.</p><v-btn v-for="component in unknownDrives" :key="component.id" variant="text" @click="emit('editComponent',component)">Classify {{component.name}}</v-btn></details>
</section>
<section class="panel build-notes control-stack"><h2>2. Destination and capacity assumptions</h2><p>With no measured usage, retain each array’s current usable capacity. A usage measurement applies to every PC in that planning group: enter the largest measured usage and record its source/date. Required usable capacity = used × (1 + growth) ÷ (1 − free-space reserve), rounded up, with pinned minimums enforced.</p><v-select v-model="scenario.mode" :items="[{title:'Destination configuration (all hardware)',value:'configuration'},{title:'SSD replacement assistant',value:'ssd'}]" label="Transition method" /><details class="mb-4"><summary>Capacity sizing and spare parts</summary><div class="form-grid mt-4"><v-text-field v-model.number="scenario.growthPercent" label="Expected data growth (%)" type="number" min="0" max="500" /><v-text-field v-model.number="scenario.freePercent" label="Free-space reserve (%)" type="number" min="0" max="90" /><v-text-field v-model.number="scenario.sparePercent" label="Spare parts (% of new or reserved units)" type="number" min="0" max="100" /></div></details><p v-if="scenario.mode==='ssd'">Drive counts, RAID layouts, and existing mounting/controller/wiring assignments are preserved. An interface or form-factor change must pass the existing compatibility checks. Adapter purchases and layout redesign require a separate engineering review.</p>
<p v-if="scenario.mode==='configuration'">Create or duplicate a destination in Configurations first, including the desired front bays, drive cages, adapters, controllers and other hardware. Save it, then select it for each planning group here. Map source storage to destination arrays when their names or layouts differ; merged arrays must fit their combined capacity needs.</p><v-alert v-if="scenario.mode==='ssd'&&!ssdCandidates(db).length" type="info">No classified SSDs with capacity are available. Add or classify SSD models in Component catalog to compare them here.</v-alert>
<div v-if="scenario.mode==='configuration'&&cohorts.length>1" class="bulk-toolbar"><v-select v-model="sharedDestination" :items="destinationChoices" label="One destination for all planning groups" hide-details /><v-btn variant="outlined" :disabled="!sharedDestination" @click="applySharedDestination">Apply to all groups</v-btn></div><p v-if="!cohorts.length">Select PCs above to build planning groups.</p>
</section>
<section v-for="(cohort,index) in cohorts" :key="cohort.id" class="panel build-notes control-stack transition-cohort"><div class="section-head"><div><h3>{{cohort.name}} · group {{index+1}}</h3><p>{{cohort.members.length}} PCs · {{cohort.members[0].provisional?'Hardware assumption':'Recorded hardware'}} · {{cohort.members.map(b=>b.pc.name).slice(0,5).join(', ')}}{{cohort.members.length>5?'…':''}}</p></div><v-btn v-if="scenario.mode==='ssd'" variant="outlined" :disabled="!!validationError" @click="suggest(cohort)">Suggest SSDs</v-btn></div><v-alert v-if="reuseChoices(cohort).length" type="info" variant="tonal" class="control-stack transition-reuse"><p>Reuse available inputs from {{reuseChoices(cohort).length===1?reuseChoices(cohort)[0].name:'a configured group'}}. Current entries stay as entered. Capacity inputs copy only for matching drive models, quantities, array roles and RAID; confirm the evidence covers these PCs.</p><v-select v-if="reuseChoices(cohort).length>1" v-model="reuseSource[cohort.id]" label="Reuse inputs from group" :items="reuseChoices(cohort).map(choice=>({title:choice.name,value:choice.key,props:{subtitle:reuseSummary(choice)}}))" /><template v-if="reusePreview(cohort)"><p>{{reuseSummary(reusePreview(cohort)!)}}</p><ul v-if="Object.keys(reusePreview(cohort)!.policies).length"><li v-for="(entry,id) in reusePreview(cohort)!.policies" :key="id">{{cohort.segments.find(segment=>segment.id===id)?.name||id}}: {{entry.evidence||'No usage evidence recorded'}}</li></ul><p v-if="reusePreview(cohort)!.skipped">{{reusePreview(cohort)!.skipped}} array inputs will stay blank because the storage layout differs.</p></template><v-btn variant="outlined" :disabled="!reusePreview(cohort)" @click="copyInputs(cohort)">Reuse available group inputs</v-btn></v-alert><v-select v-if="scenario.mode==='configuration'" v-model="scenario.destinationIds[cohort.id]" :items="destinationChoices" label="Destination configuration for this group" /><v-btn v-if="scenario.mode==='configuration'&&scenario.destinationIds[cohort.id]" variant="text" @click="emit('openRelated',{kind:'configuration',id:scenario.destinationIds[cohort.id]})">Open destination configuration</v-btn><p v-if="!cohort.segments.length">No disk storage is recorded for this group.</p>
<div v-for="segment in cohort.segments" :key="segment.id" class="transition-segment"><h4>{{segment.name}} · {{segment.raid}}</h4><p>{{segment.placements.reduce((n,p)=>n+p.quantity,0)}} drives per PC · currently {{gb(segment.originalGb)}} usable · required {{gb(requiredSegmentGb(segment,policy(cohort,segment),scenario))}}<span v-if="policy(cohort,segment)?.usedGb!==undefined"> with measured usage</span><span v-else> to retain capacity</span></p>
<div class="form-grid"><v-text-field :model-value="policy(cohort,segment)?.usedGb" label="Largest measured used capacity per PC (GB)" type="number" min="0" clearable hint="Leave blank to retain current usable capacity." persistent-hint @update:model-value="v=>updatePolicy(cohort,segment,'usedGb',v)" /><v-text-field :model-value="policy(cohort,segment)?.evidence||''" label="Usage evidence / date" hint="For example: filesystem report, 2026-10-10, all PCs checked." persistent-hint @update:model-value="v=>updatePolicy(cohort,segment,'evidence',v)" /><v-select v-if="scenario.mode==='configuration'" :model-value="policy(cohort,segment)?.targetSegmentId||segment.id" :items="destinationSegments(cohort).filter(s=>s.role===segment.role).map(s=>({title:`${s.name} · ${s.raid} · ${gb(s.originalGb)} usable`,value:s.id}))" label="Destination storage segment" @update:model-value="v=>updatePolicy(cohort,segment,'targetSegmentId',v)" /><v-select v-else :model-value="policy(cohort,segment)?.replacementId" :items="choices(cohort,segment).map(c=>({title:`${c.name} · ${gb(c.usableGb)} usable · ${c.interface||'?'} / ${c.size||'?'} · ${c.eligible?'Fits capacity/checks':'Blocked'}`,value:c.id}))" label="Target SSD for this array" clearable @update:model-value="v=>updatePolicy(cohort,segment,'replacementId',v)" /></div>
<details v-if="scenario.mode==='ssd'"><summary>Compare {{choices(cohort,segment).length}} SSD options</summary><p>Suggestions prefer a usable existing SSD model, then the smallest eligible capacity, with free stock as a tie-breaker. Each option is checked in this array; the complete combination is reviewed below.</p><div v-for="option in choices(cohort,segment)" :key="option.id" class="transition-option"><strong>{{option.name}}</strong><p>{{gb(option.capacityGb)}} per drive · {{gb(option.usableGb)}} usable per PC · {{option.interface}} / {{option.size}} · {{option.free}} free units</p><ul v-if="option.errors.length"><li v-for="finding in option.errors" :key="finding">{{finding}}</li></ul><p v-else>Meets this array’s capacity and compatibility checks. Manufacturer specifications and migration feasibility still need review.</p></div></details>
</div></section>
<section class="panel build-notes control-stack"><h2>3. Review targets and procurement</h2><v-btn color="primary" :disabled="!scenario.pcIds.length||!!validationError" @click="review">Review transition plan</v-btn><p v-if="report" role="status">{{report.included}} PCs included in demand · {{report.blocked}} blocked · {{report.provisional}} use hardware assumptions.</p><v-alert v-if="report?.blocked" type="warning" class="my-4">Blocked PCs are excluded from the order estimate. Resolve their findings to get a complete fleet total.</v-alert><v-alert v-if="reviewed&&!currentReview" type="info" class="my-4">The scope, assumptions, choices, or workspace changed. Review the plan again.</v-alert>
<v-checkbox v-if="report?.blocked" v-model="blockersOnly" label="Show only blocked PCs" hide-details class="mb-4" /><RecordTable v-if="report?.pcs.length" label="Transition targets and findings" :headers="resultHeaders" :items="resultRows"><template #name="{item}"><button type="button" v-if="db.pcs.some(pc=>pc.id===item.id)" class="table-name" @click="emit('openRelated',{kind:'pc',id:item.id})">{{item.name}}</button><span v-else>{{item.name}}</span></template><template #provisional="{item}">{{item.provisional?'Hardware assumption':'Recorded hardware'}}</template><template #afterBoot="{item}">{{gb(item.beforeBoot)}} → {{gb(item.afterBoot)}}</template><template #afterData="{item}">{{gb(item.beforeData)}} → {{gb(item.afterData)}}</template><template #reviewText="{item}"><details :open="item.issues.length>0"><summary>{{item.status}} · {{item.issues.length}} blockers · {{item.warnings.length}} review notes</summary><ul><li v-for="finding in [...item.issues,...item.warnings]" :key="finding">{{finding}}</li></ul><div class="heading-actions"><v-btn v-if="db.pcs.some(pc=>pc.id===item.id)" variant="text" size="small" @click="emit('editPc',db.pcs.find(pc=>pc.id===item.id)!)">Edit PC survey</v-btn><v-btn variant="text" size="small" @click="removePCs([item.id])">Remove from plan</v-btn></div><p>{{item.removed}} installed parts removed. Arrange backup, restore/clone, maintenance window, validation and recommissioning.</p><ul><li v-for="change in item.changes.filter((c:{added:number;removed:number})=>c.added||c.removed)" :key="change.name">{{change.name}}: target {{change.target}}, retain {{change.retained}}, add {{change.added}}, remove {{change.removed}}</li></ul></details></template></RecordTable>
<h3 class="mt-5">Parts order estimate</h3>
<p>Compare the order using confirmed stock with the order if inspection confirms possible reuse. Both include the spare-parts allowance. Blocked PCs contribute no demand.</p>
<div v-if="report?.procurement.length" class="transition-order-totals" aria-label="Fleet order totals" role="status"><div><span>Using confirmed stock</span><strong>{{orderCount.toLocaleString()}} units</strong></div><div><span>If hardware assumptions are confirmed</span><strong>{{conditionalOrderCount.toLocaleString()}} units</strong><small v-if="!hasAssumedReuse">No additional assumed reuse in this estimate.</small><small v-else>Confirm the assumed parts before using this lower estimate.</small></div></div>
<details><summary>How the order is calculated</summary><p>Destination mode counts every component, retains serviceable installed parts by model within each PC, and reuses matching reservations once. The SSD assistant retains drives in their existing positions. Free stock excludes all reservations, installations and non-serviceable lots. Removed parts are not treated as free stock. Possible assumed reuse is separate from inventory. Review relocation, wiring and source evidence before ordering.</p></details>
<div v-if="report?.procurement.length" class="form-grid"><v-select v-model="estimateBasis" label="Filter purchases using" :items="[{title:'Confirmed stock',value:'confirmed'},{title:'Assumptions confirmed',value:'conditional'}]" /><v-checkbox v-model="orderOnly" label="Only parts to order" hide-details /></div>
<RecordTable v-if="orderRows.length" label="Parts procurement estimate" :headers="orderHeaders" :items="orderRows"><template #componentSummary="{item}"><strong>{{item.name}}</strong><small>{{item.category}}<span v-if="item.capacityGb!==null"> · {{gb(item.capacityGb)}} per unit</span><span v-if="item.interface!=='—'"> · {{item.interface}} / {{item.size}}</span></small></template><template #breakdown="{item}"><details><summary>Stock breakdown</summary><dl class="transition-stock-breakdown"><dt>Retain installed</dt><dd>{{item.retained}}</dd><dt>Possible assumed reuse</dt><dd>{{item.assumedRetained}}</dd><dt>Held for these PCs</dt><dd>{{item.reserved}}</dd><dt>Free serviceable stock</dt><dd>{{item.free}}</dd><dt>Spares using confirmed stock</dt><dd>{{item.spares}}</dd></dl></details></template></RecordTable>
<div v-else class="control-stack"><p>{{report?.procurement.length?'No purchases match this filter. The totals above still cover all included PCs.':'No resolved parts demand yet.'}}</p><v-btn v-if="report?.procurement.length&&orderOnly" variant="text" @click="orderOnly=false">Show all components</v-btn></div>
<v-btn variant="outlined" :disabled="!currentReview||!report?.procurement.length||!!report.blocked||stale" @click="exportOrder">Export order CSV</v-btn><p class="form-hint" role="status">{{exportReason}}</p>

</section>
<section class="panel build-notes control-stack"><h2>4. Plan the rollout</h2><p>Choose representative pilot PCs, then stage the remaining included machines in waves. Waves are planning groups; the order estimate above remains pooled across the whole fleet.</p><div class="form-grid"><v-select v-model="scenario.rollout.pilotPCIds" :items="pilotChoices" label="Pilot PCs" multiple chips closable-chips clearable /><v-text-field v-model.number="scenario.rollout.waveSize" label="PCs per rollout wave" type="number" min="1" max="500" /><v-select v-model="scenario.rollout.method" label="Migration approach" :items="['Hardware change only (no data migration)','Backup and restore','Clone with partition review','Reimage and restore data']" /><v-text-field v-model="scenario.rollout.maintenanceWindow" label="Maintenance window / owner" /><v-textarea v-model="scenario.rollout.rollbackNotes" label="Rollback and removed-parts disposition" rows="2" /></div>
<RecordTable v-if="report?.waves.length" label="Proposed pilot and rollout waves" :headers="waveHeaders" :items="report.waves" />
<ol class="transition-handoff"><li>Inspect PCs with incomplete surveys and reconcile their assumed configurations before ordering. Verify measured usage, filesystem/partition shrink limits, SSD endurance, boot support, mounting, controllers, and backups.</li><li>Approve the complete destination configurations, including bays, cages, adapters and controllers. Reserve or order the reviewed parts.</li><li>Run the pilot in its maintenance window. Install the planned hardware and migrate data as needed, validate software and data, and recommission before returning it to service.</li><li>Proceed through the remaining waves after pilot acceptance. Record installed identities and configuration assignments, then wipe, retain, or dispose of removed parts according to the rollback plan.</li></ol><p>These rollout assumptions are saved with the workspace plan and its exported file. Execution and per-machine completion tracking are future work.</p>
</section>
<BulkRecordEditor ref="bulkEditor" :request="bulkRequest" :db="db" @close="bulkRequest=null" @reload="emit('reload')" @notify="message=>emit('notify',message)" /></div></div>
</template>
